components.css:
.ds-primary {
  border:1px solid #88f0ee;
  background:var(--cyan);
  color:#05202a;
  border-radius:5px;
  min-height:48px;
  padding:12px 20px;
  font:600 11px var(--mono);
  letter-spacing:1.1px;
  display:flex;
  justify-content:center;
  align-items:center;
  gap:12px;
  transition:background .2s,box-shadow .2s}
.ds-primary:hover {
  background:#a7ffff;
  box-shadow:0 6px 24px #6ae9ec15}
.ds-primary:disabled {
  opacity:.45;
  cursor:wait}
.ds-primary {font-family:var(--mono);cursor:pointer}.ds-primary:focus-visible {outline:2px solid var(--cyan);outline-offset:5px}

.ds-secondary {
  background:#10232e;
  border:1px solid #3d5968;
  border-radius:4px;
  padding:11px 14px;
  min-height:42px;
  color:var(--text);
  font-size:11px;
  transition:border-color .2s,background .2s}
.ds-secondary:hover {
  border-color:var(--cyan);
  background:#183540}
.ds-secondary {font-family:var(--sans);cursor:pointer}.ds-secondary:focus-visible {outline:2px solid var(--cyan);outline-offset:5px}

.ds-text {
  border:0;
  background:transparent;
  padding:6px 0;
  color:#b1c9d4;
  font-size:11px;
  text-decoration:underline;
  text-underline-offset:4px}
.ds-text:hover {
  color:var(--cyan)}
.ds-text {font-family:var(--sans);cursor:pointer}.ds-text:focus-visible {outline:2px solid var(--cyan);outline-offset:5px}
.ds-arrow {width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.5;vertical-align:middle}

.ds-input {
  width:100%;
  height:46px;
  border:1px solid #283c4a;
  background:#0b1622;
  border-radius:5px;
  padding:0 13px;
  color:var(--text);
  transition:border-color .2s}
.ds-input::placeholder {
  color:#8197a8;
  font-size:12px}
.ds-input:hover {
  border-color:#426372}
.ds-input:focus {
  border-color:var(--cyan);
  outline:1px solid var(--cyan)}
.ds-input {font:14px/1.6 var(--sans);caret-color:var(--cyan)}

.ds-nav {
  display:flex;
  gap:34px;
  margin-left:auto;
  height:100%;
  align-items:center}
.ds-link {
  border:0;
  background:none;
  color:var(--muted);
  height:100%;
  padding:0;
  position:relative;
  font-size:13px}
.ds-link.ds-active {
  color:var(--text)}
.ds-link.ds-active:after {
  content:'';
  position:absolute;
  bottom:-1px;
  height:2px;
  left:0;
  right:0;
  background:var(--cyan)}
.ds-link:hover {
  color:var(--cyan)}
.ds-nav{height:64px;margin-left:0;font-family:var(--sans)}.ds-link{cursor:pointer}.ds-link:focus-visible {outline:2px solid var(--cyan);outline-offset:5px}

.ds-prediction {
  display:flex;
  align-items:center;
  gap:12px;
  border:1px solid #263c4a;
  border-radius:5px;
  margin-top:8px;
  padding:13px;
  background:#0a1520;
  cursor:pointer;
  position:relative;
  transition:background .2s,border-color .2s}
.ds-prediction:hover {
  border-color:#537786}
.ds-prediction:has(input:checked) {
  border-color:#71dce0;
  background:#102a34}
.ds-radio {
  width:14px;
  height:14px;
  border:1px solid #5b7384;
  border-radius:50%;
  flex-shrink:0;
  display:grid;
  place-items:center}
.ds-prediction input:checked+.ds-radio {
  border-color:var(--cyan)}
.ds-prediction input:checked+.ds-radio:after {
  content:'';
  width:6px;
  height:6px;
  background:var(--cyan);
  border-radius:50%}
.ds-prediction strong {
  display:block;
  font:500 12px var(--sans)}
.ds-prediction small {
  display:block;
  font:11px var(--sans);
  color:var(--muted);
  margin-top:4px}
.ds-prediction{color:var(--text)}.ds-prediction input{position:absolute;opacity:0;width:1px;height:1px}.ds-prediction:has(input:focus-visible){outline:2px solid var(--cyan);outline-offset:3px}

.ds-modes {
  display:grid;
  grid-template-columns:1fr 1fr;
  border:1px solid #283c4a;
  border-radius:5px;
  background:#0b1622;
  padding:4px;
  gap:4px}
.ds-modes label {
  position:relative;
  cursor:pointer}
.ds-modes label>span {
  display:flex;
  align-items:center;
  justify-content:center;
  gap:9px;
  padding:9px 6px;
  font:11px var(--mono);
  border:1px solid transparent;
  border-radius:3px}
.ds-modes small {
  font:11px var(--sans);
  color:var(--muted)}
.ds-modes input:checked+span {
  background:#17343d;
  border-color:#37636a;
  color:var(--cyan)}
.ds-modes{color:var(--text)}.ds-modes input{position:absolute;opacity:0;width:1px;height:1px}.ds-modes input:focus-visible+span{outline:2px solid var(--cyan);outline-offset:3px}
